code.cpp:
class Solution {
public:
    int countPairs(vector<int>& deliciousness) {
        const int MOD = 1000000007;
        unordered_map<int, int> seen;
        long long ans = 0;
        for (int x : deliciousness) {
            for (int p = 1; p <= (1 << 21); p <<= 1) {
                int target = p - x;
                auto it = seen.find(target);
                if (it != seen.end()) {
                    ans += it->second;
                }
            }
            seen[x]++;
        }
        return (int)(ans % MOD);
    }
};
